import{_ as e,c as s,o as i,b0 as t}from"./chunks/framework.Becqh7-x.js";const l="/linux-dev-docs/assets/image-20241020122703236.DIoCMcAi.png",n="/linux-dev-docs/assets/image-20241020123026934.DP6dIJRU.png",p="/linux-dev-docs/assets/image-20241020123511827.BU5be36o.png",d="/linux-dev-docs/assets/image-20241021225541847.C5C3gaQE.png",r="/linux-dev-docs/assets/image-20241021225134362.DzAGMidh.png",o="/linux-dev-docs/assets/image-20241021225239537.S4MPxvK-.png",v=JSON.parse('{"title":"LV130-横竖屏切换","description":null,"frontmatter":{"title":"LV130-横竖屏切换","date":"2026-01-07T19:20:53.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/application/lcd/126d2c7e06f5317653d85ef8","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-07T19:20:53.791Z","fulluuid":"653d85ef8a9f49bc8c5ae95eddd1008e","useduuid":"653d85ef8"}},"headers":[],"relativePath":"sdoc/application/lcd/126d2c7e06f5317653d85ef8.md","filePath":"sdoc/20-应用开发/20-LCD应用/LV130-横竖屏切换.md","lastUpdated":1768604092000}'),h={name:"sdoc/application/lcd/126d2c7e06f5317653d85ef8.md"};function c(u,a,m,g,_,b){return i(),s("div",null,[...a[0]||(a[0]=[t('<h1 id="lv130-横竖屏切换" tabindex="-1">LV130-横竖屏切换 <a class="header-anchor" href="#lv130-横竖屏切换" aria-label="Permalink to &quot;LV130-横竖屏切换&quot;">​</a></h1><h2 id="一、横竖屏切换基本原理" tabindex="-1">一、横竖屏切换基本原理 <a class="header-anchor" href="#一、横竖屏切换基本原理" aria-label="Permalink to &quot;一、横竖屏切换基本原理&quot;">​</a></h2><p>我使用的是正点原子的开发板，配套使用的这些 LCD 屏都是横屏显示的，包括正点原子 4.3 寸 480*272、 4.3 寸 800*480、 7 寸800*480、 7 寸 1024*600 以及 10.1 寸 1280*800 等这些 RGB LCD 屏； LCD 屏正向放置情况下（以 800*480分辨率为例） ，它的左上角就是坐标(0, 0)、左下角坐标是(0, 480-1)、右上角坐标是(800-1, 0)、右下角坐标是(800-1, 480-1)，如下所示：</p><img src="'+l+'" alt="image-20241020122703236" style="zoom:50%;"><p>这是硬件上固定的，它是一种硬件属性，有些LCD屏控制芯片支持不同的扫描方式，实现不同方向的显示，但是这样的话就要修改LCD驱动，哪有办法不修改驱动吗？我们后面再说。像素点的排列顺序是从左到右、从上到下， 我们对 LCD 上不同像素点进行操作时，需要找到该像素点对应的显存地址，同样也是基于这种标准来的； 假设显存基地址为(unsignedchar *)base， 那么定位一个(x, y)坐标像素点对应的地址的公式为 :</p><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>base + (y * width + x) * pix_bytes</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>其中pix_bytes 表示一个像素点使用 pix_bytes 个字节来描述。LCD 像素点与显存对应关系示意图如下：</p><img src="'+n+'" alt="image-20241020123026934" style="zoom:50%;"><p>在很多的应用场合中，往往需要以竖屏的方式来显示画面，例如手机就是一个很好的例子，我们的手机都是竖屏方式显示的；甚至还有一些电子产品既能支持横屏也能支持竖屏显示，当然这是针对应用程序而言。 那我们的应用程序中如何将 LCD 屏修改为竖屏显示呢？</p><p>上面所示屏幕， 如果我们要将其作为竖屏显示，如在应用程序中将左下角作为起点(0, 0)，那么左上角对应就是(480-1, 0)、右下角对应就是(0, 800-1)、右上角对应就是(480-1, 800-1)，如下图所示：</p><img src="'+p+'" alt="image-20241020123511827" style="zoom:50%;"><p>以上便是竖屏显示情况下，其中的一种坐标分布情况，当然这是应用程序认为的一种坐标分布，对于LCD 硬件来说， 实际物理上的起点坐标依然是横屏中左上角的位置。</p><p>那么在上图中竖屏这种情况下， 应用程序的坐标对应的像素点，它的显存地址就不能使用这个公式计算了：</p><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>base + (y * width + x) * pix_bytes</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>竖屏方式下，起点坐标(0, 0)对应的实际物理坐标是(0, 480-1)，同理它的显存地址也是通过实际物理坐标(0, 480-1)这个坐标计算而来、而不是通过(0, 0)计算。</p><img src="'+d+'" alt="image-20241021225541847"><p>在竖屏方式下，应用程序的(x&#39;, y&#39;)坐标点对应的显存地址可通过如下公式进行计算：</p><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>base + ((height - 1- x&#39;) * width + y&#39;)) * pix_bytes;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="二、使用实例" tabindex="-1">二、使用实例 <a class="header-anchor" href="#二、使用实例" aria-label="Permalink to &quot;二、使用实例&quot;">​</a></h2><h3 id="_1-实例1——画线" tabindex="-1">1. 实例1——画线 <a class="header-anchor" href="#_1-实例1——画线" aria-label="Permalink to &quot;1. 实例1——画线&quot;">​</a></h3><h4 id="_1-1-源码实现" tabindex="-1">1.1 源码实现 <a class="header-anchor" href="#_1-1-源码实现" aria-label="Permalink to &quot;1.1 源码实现&quot;">​</a></h4><p>可以看这里：<a href="https://gitee.com/linux-dev-org/imx6ull-app-demo/tree/master/LV18_LCD_DEVICE/11_lcd_vertical_display" target="_blank" rel="noreferrer">LV18_LCD_DEVICE/11_lcd_vertical_display · linux-dev-org/imx6ull-app-demo</a></p><img src="'+r+'" alt="image-20241021225134362"><h4 id="_1-2-开发板验证" tabindex="-1">1.2 开发板验证 <a class="header-anchor" href="#_1-2-开发板验证" aria-label="Permalink to &quot;1.2 开发板验证&quot;">​</a></h4><p>编译后执行以下命令：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./app_demo</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>然后就会看到显示屏进行横竖方向画线。</p><h3 id="_2-实例2——显示汉字" tabindex="-1">2. 实例2——显示汉字 <a class="header-anchor" href="#_2-实例2——显示汉字" aria-label="Permalink to &quot;2. 实例2——显示汉字&quot;">​</a></h3><h4 id="_2-1-源码实现" tabindex="-1">2.1 源码实现 <a class="header-anchor" href="#_2-1-源码实现" aria-label="Permalink to &quot;2.1 源码实现&quot;">​</a></h4><p>可以看这里：<a href="https://gitee.com/linux-dev-org/imx6ull-app-demo/tree/master/LV18_LCD_DEVICE/12_lcd_vertical_show_font" target="_blank" rel="noreferrer">LV18_LCD_DEVICE/12_lcd_vertical_show_font · linux-dev-org/imx6ull-app-demo</a></p><img src="'+o+`" alt="image-20241021225239537"><h4 id="_2-2-开发板验证" tabindex="-1">2.2 开发板验证 <a class="header-anchor" href="#_2-2-开发板验证" aria-label="Permalink to &quot;2.2 开发板验证&quot;">​</a></h4><p>编译完成之后执行以下命令：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./app_demo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./data/simsun.ttc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 24</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 竖屏显示</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./app_demo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./data/simsun.ttc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 24</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 横屏显示</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div>`,34)])])}const x=e(h,[["render",c]]);export{v as __pageData,x as default};
